var e=[{title:`Statikus nyújtás`,text:`A statikus nyújtás gyengéden tart egy izmot vagy ízületet a kényelmes tartomány vége közelében. Egy falnál végzett vádlinyújtás vagy egy támasztott csípőhajlító-nyújtás például rövid ideig tartható pattogás nélkül. Enyhe feszülésnek kell érződnie, soha nem éles fájdalomnak vagy zsibbadásnak.`},{title:`Dinamikus nyújtás`,text:`A dinamikus nyújtás újra és újra végigmegy egy hasznos tartományon: kontrollálható lábhintázások, karkörzések, váltott kitörések. Minden ismétlés tudatos, nem pattogó vagy kapkodó. Ezek a gyakorlatok természetesen illeszkednek a futás, az emelés és a sport bemelegítésébe.`},{title:`Mikor melyiket használd`,text:`Robbanékony erőfeszítés előtt általában a fokozatos dinamikus mozgás és maga a gyakorlat próbája működik a legjobban. A hosszú, intenzív statikus nyújtás közvetlenül előtte rövid időre csökkentheti az erőt vagy a teljesítményt, néhány rövid tartás viszont kevésbé aggályos. Edzés után vagy külön alkalommal a statikus nyújtás észszerű módja a hajlékonyságon való munkának.`},{title:`Mennyit végezz`,text:`Használj rövid, kényelmes tartásokat, és ismételd őket hetekig, ahelyett hogy egyetlen alkalommal erőltetnél egy új tartományt. A dinamikus gyakorlatoknál kis tartománnyal kezdj, és csak addig szélesítsd, amíg a mozdulat kontrollált marad. A nyújtásnak nem kell fájnia ahhoz, hogy működjön, és a nagyobb hajlékonyság nem segít minden feladatban.`},{title:`Mit nem ígérhet a nyújtás`,text:`A dinamikus gyakorlatokkal készülj fel az aktív mozgásra, a statikus tartásokat pedig akkor használd, ha a hajlékonyság a cél. Egyik sem tesz sérülésállóvá, és nem előzi meg megbízhatóan az izomlázat. Ha a fájdalom nem múlik, kérj tanácsot orvostól vagy gyógytornásztól, aki rád szabott útmutatást ad.`}];var s=[{label:`ACE 2026: gyakorlati nyújtási útmutató`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: mozgékonyság és hajlékonyság`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: gyengéd levezető gyakorlatok`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var n={sections:e,sources:s};export{n as default,e as sections,s as sources};